 "content": "def transform(grid):
    """Draw the fixed color-coded strokes and their 2/vertical intersections."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (1, 2, 3, 6):
                points.setdefault(color, []).append((r, c))

    def put(r, c, color):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = color

    # Color 1: a two-cell rightward bar, capped one row above its end.
    for r, c in points.get(1, []):
        put(r, c + 1, 5)
        put(r, c + 2, 5)
        put(r - 1, c + 2, 1)

    # Color 2: a four-cell leftward stroke.
    for r, c in points.get(2, []):
        for d in range(1, 4):
            put(r, c - d, 5)
        put(r, c - 4, 2)

    # Color 3: a three-cell downward stroke.
    for r, c in points.get(3, []):
        for d in range(1, 3):
            put(r + d, c, 5)
        put(r + 3, c, 3)

    # Color 6: a six-cell upward stroke.
    for r, c in points.get(6, []):
        for d in range(1, 6):
            put(r - d, c, 5)
        put(r - 6, c, 6)

    # When the downward 3-stroke terminates on the same row as a 1 marker,
    # bridge the gap in 5 (as in the demonstrated aligned endpoint case).
    for r3, c3 in points.get(3, []):
        end_r = r3 + 3
        for r1, c1 in points.get(1, []):
            if r1 == end_r:
                lo, hi = sorted((c3, c1))
                for c in range(lo + 1, hi):
                    put(end_r, c, 5)

    # The 2-stroke crossing a vertical 3- or 6-stroke is marked 4; continue
    # that crossing diagonally down-left to the edge.
    vertical = []
    for r, c in points.get(3, []):
        vertical.append((c, r, r + 3))
    for r, c in points.get(6, []):
        vertical.append((c, r - 6, r))
    for r2, c2 in points.get(2, []):
        left, right = c2 - 4, c2
        for c, top, bottom in vertical:
            if left <= c <= right and top <= r2 <= bottom:
                put(r2, c, 4)
                rr, cc = r2 + 1, c - 1
                while rr < h and cc >= 0:
                    put(rr, cc, 4)
                    rr += 1
                    cc -= 1

    return out
